#!/bin/zsh
# Assemble placeholders and build PDFs with pandoc + tectonic (adapted from LLM_Calc/paper/build.sh).
#   {{table:NAME}}            -> tables/NAME.md (generated by `uv run make_tables.py` from results/registry/)
#   {{file:PATH}}             -> contents of PATH (relative to paper/)
#   {{section:PATH|HEADING}}  -> the section of PATH under HEADING, up to the next heading
set -euo pipefail
cd "$(dirname "$0")"
mkdir -p build
# arXiv: the manuscript as is (it carries its own appendix). If a supplement.md is added later, add its
# sections here as LLM_Calc's build.sh does.
cp manuscript.md arxiv.md
docs=(manuscript arxiv); [ -f supplement.md ] && docs=(manuscript supplement arxiv)
for doc in $docs; do
  python3 - "$doc" <<'PY'
import re, sys
from pathlib import Path
doc = sys.argv[1]
text = Path(f"{doc}.md").read_text()
def section(path, heading):
    src = Path(path).read_text()
    start = src.index(heading) + len(heading)
    level = heading.split()[0]
    m = re.search(rf"^{re.escape(level)} ", src[start:], flags=re.M)
    return src[start : start + m.start()] if m else src[start:]
def repl(m):
    kind, arg = m.group(1), m.group(2)
    if kind == "table":
        return Path(f"tables/{arg}.md").read_text()
    if kind == "file":
        return Path(arg).read_text()
    path, heading = arg.split("|", 1)
    return section(path, heading)
out = re.sub(r"\{\{(table|file|section):([^}]+)\}\}", repl, text)
# Pandoc needs a blank line before a list that follows a paragraph line.
lines, fixed, in_code = out.split("\n"), [], False
for line in lines:
    if line.startswith("```"):
        in_code = not in_code
    is_item = re.match(r"^\s*(- |\d+\. )", line) is not None
    prev = fixed[-1] if fixed else ""
    prev_item = re.match(r"^\s*(- |\d+\. )", prev) is not None or prev.startswith("  ")
    if not in_code and is_item and prev.strip() and not prev_item and not prev.startswith("|"):
        fixed.append("")
    fixed.append(line)
out = "\n".join(fixed)
# Pipe-table column widths: pandoc makes wide tables' columns proportional to the dashes in the
# separator row, which are all equal in our tables. Set them from the content instead.
def widths(block):
    rows = [[c.strip() for c in l.strip().strip("|").split("|")] for l in block]
    n = len(rows[0])
    body = [r for i, r in enumerate(rows) if i > 1 and len(r) == n]
    head = rows[0]
    w = []
    for j in range(n):
        longest = max(len(r[j]) for r in body)
        words = max(len(x) for r in body + [head] for x in r[j].split() or [""])
        w.append(max(words, min(longest, 40), 4))
    return "|" + "|".join("-" * x for x in w) + "|"
lines, res, i = out.split("\n"), [], 0
while i < len(lines):
    if lines[i].startswith("|") and i + 1 < len(lines) and re.match(r"^\|(\s*:?-+:?\s*\|)+\s*$", lines[i + 1]):
        j = i
        while j < len(lines) and lines[j].startswith("|"):
            j += 1
        block = lines[i:j]
        block[1] = widths(block)
        res += block
        i = j
    else:
        res.append(lines[i])
        i += 1
out = "\n".join(res)
Path(f"build/{doc}.md").write_text(out)
PY
  [ "$doc" = arxiv ] && continue  # built below from the arXiv package itself
  pandoc "build/$doc.md" -o "$doc.pdf" --pdf-engine=tectonic --citeproc \
    -V geometry:margin=1.8cm -V fontsize=9pt -V linestretch=1.1 -V colorlinks=true \
    -V mainfont="Helvetica" -V monofont="Menlo" --resource-path=.:figures:build \
    2> "build/$doc.log" || { tail -20 "build/$doc.log"; exit 1; }
  echo "built paper2/$doc.pdf"
done

# arXiv source package, in the format of the author's earlier arXiv papers: article 11pt, 1in
# margins, natbib + plainnat, and a tarball of main.tex, main.bbl, refs.bib and figures/.
# arXiv does not reliably run BibTeX, so main.bbl ships; refs.bib ships too, or \cite keys can
# resolve to [?]. The package is verified by building it from its own contents.
rm -rf build/arxiv && mkdir -p build/arxiv/figures
pandoc build/arxiv.md -s --natbib --shift-heading-level-by=-1 -o build/arxiv/main.tex \
  -V documentclass=article -V fontsize=11pt -V geometry:margin=1in -V colorlinks=true \
  -V linkcolor=blue -V citecolor=blue -V urlcolor=blue
python3 - <<'PY'
import re
from pathlib import Path
path = Path("build/arxiv/main.tex")
tex = path.read_text(encoding="utf8")
# Author block as in the earlier papers.
tex = re.sub(r"\\author\{.*?\}\n", lambda m: "\\author{Nicol\\'as Vera Z\\'u\\~niga\\\\\nIndependent Researcher, Chile\\\\\n\\texttt{nicovera@quetru.cl}}\n\\date{}\n", tex, count=1, flags=re.S)
# Abstract section -> abstract environment.
m = re.search(r"\\section\{Abstract\}\\label\{abstract\}\n(.*?)(\n\\section\{)", tex, flags=re.S)
tex = tex[: m.start()] + "\\begin{abstract}\n" + m.group(1).strip() + "\n\\end{abstract}\n" + tex[m.start(2):]
# Drop horizontal rules from the Markdown '---' separators.
tex = re.sub(r"\\begin\{center\}\\rule\{0\.5\\linewidth\}\{0\.5pt\}\\end\{center\}\n", "", tex)
# Bibliography where the References heading is (natbib prints its own heading).
# (pandoc's natbib preamble already sets \bibliographystyle{plainnat}; a second one makes BibTeX report an error.)
style = "" if "\\bibliographystyle{" in tex else "\\\\bibliographystyle{plainnat}\n"
tex = re.sub(r"\\section\{References\}\\label\{references\}\n", style + "\\\\bibliography{refs}\n", tex, count=1)
tex = re.sub(r"\n\\bibliography\{refs\.bib\}\n", "\n", tex)
# Newer pandoc emits \\renewcommand\\refname{References} instead of a References section.
tex = tex.replace("\\renewcommand\\refname{References}", "\\bibliography{refs}", 1)
tex = re.sub(r"\\begin\{CSLReferences\}.*?\\end\{CSLReferences\}\n", "", tex, flags=re.S)
tex = re.sub(r"\\hypertarget\{refs\}\{\}\n", "", tex)
# arXiv compiles with pdfLaTeX: declare the non-ASCII symbols we use (no-op under XeTeX).
decl = r"""\ifPDFTeX
\DeclareUnicodeCharacter{2265}{\ensuremath{\geq}}
\DeclareUnicodeCharacter{2264}{\ensuremath{\leq}}
\DeclareUnicodeCharacter{00D7}{\ensuremath{\times}}
\DeclareUnicodeCharacter{2192}{\ensuremath{\rightarrow}}
\DeclareUnicodeCharacter{00B5}{\ensuremath{\mu}}
\DeclareUnicodeCharacter{00B0}{\ensuremath{^{\circ}}}
\DeclareUnicodeCharacter{00B1}{\ensuremath{\pm}}
\DeclareUnicodeCharacter{2212}{\ensuremath{-}}
\fi
"""
tex = tex.replace("\\begin{document}", decl + "\\begin{document}", 1)
# Tables in a smaller font with tighter columns.
tex = re.sub(r"(\\begin\{longtable\}.*?\\end\{longtable\})", lambda m: "{\\footnotesize\\setlength{\\tabcolsep}{3pt}\n" + m.group(1) + "\n}", tex, flags=re.S)
path.write_text(tex, encoding="utf8")
PY
cp refs.bib build/arxiv/
# Only the figures the manuscript uses (version 1's figures stay in figures/ as a record).
for f in $(grep -o 'figures/[A-Za-z0-9_.-]*\.png' manuscript.md | sort -u); do cp "$f" build/arxiv/figures/; done
(cd build/arxiv && tectonic -X compile main.tex --keep-intermediates >/dev/null 2>&1)
[ -f build/arxiv/main.bbl ] || { echo "FAIL: main.bbl was not produced"; exit 1; }
rm -f arxiv_source.zip
# No macOS metadata: COPYFILE_DISABLE and --no-mac-metadata keep AppleDouble ._ files out, --no-xattrs drops extended
# attributes, and the ustar format carries no pax headers (macOS tar would merge ._ files back on extraction, so the
# check below lists the members instead of extracting them).
(cd build/arxiv && COPYFILE_DISABLE=1 tar --no-mac-metadata --no-xattrs --format ustar --uid 0 --gid 0 --uname "" \
  --gname "" -czf ../../arxiv-submission.tar.gz main.tex main.bbl refs.bib figures/)
python3 - <<'PY2'
import tarfile
with tarfile.open("arxiv-submission.tar.gz") as t:
    members = t.getmembers()
names = [m.name for m in members]
bad = [n for n in names if n.split("/")[-1].startswith("._") or "__MACOSX" in n]
pax = [m.name for m in members if m.pax_headers]
files = sorted(m.name for m in members if m.isfile())
assert not bad and not pax, (bad, pax)
assert files == sorted(["main.tex", "main.bbl", "refs.bib"] + [n for n in files if n.startswith("figures/")]), files
assert all(n.endswith(".png") for n in files if n.startswith("figures/")), files
print("  tarball members:", ", ".join(files))
PY2
bst=$(grep -c '\\bibliographystyle' build/arxiv/main.tex || true)
[ "$bst" -eq 1 ] || { echo "FAIL: $bst \\bibliographystyle commands in main.tex"; exit 1; }

# VERIFY: build from the tarball alone, then check the output, not just the exit status.
rm -rf build/verify && mkdir -p build/verify
tar xzf arxiv-submission.tar.gz -C build/verify
(cd build/verify && tectonic -X compile main.tex --keep-logs >/dev/null 2>&1)
cp build/verify/main.pdf arxiv.pdf
bad=$(grep -icE "undefined (citation|reference)" build/verify/main.log || true)
marks=$(pdftotext arxiv.pdf - 2>/dev/null | grep -c '\[?\]' || true)
pages=$(pdfinfo arxiv.pdf | awk '/^Pages/{print $2}')
echo "  package : paper2/arxiv-submission.tar.gz ($pages pages)"
echo "  undefined citations/references : $bad  (must be 0)"
echo "  literal [?] markers in the PDF : $marks  (must be 0)"
[ "$bad" -eq 0 ] && [ "$marks" -eq 0 ] || { echo "  FAIL -- do not upload."; exit 1; }
echo "  OK -- verified from the tarball's own contents."
